import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r'''
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
// Cooperative tiled direct 2D convolution.
// Each CTA computes an 8x8 spatial output tile for 4 output channels.
// The CTA cooperatively stages the strided input halo tile in shared memory,
// including zero padding for out-of-range input locations.
constexpr int TILE_H = 8;
constexpr int TILE_W = 8;
constexpr int COUT_TILE = 4;
constexpr int BLOCK_THREADS = TILE_H * TILE_W * COUT_TILE;
__global__ void conv2d_forward_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int N, const int C_in, const int H_in, const int W_in,
    const int C_out, const int H_out, const int W_out,
    const int K, const int stride, const int pad)
{
    extern __shared__ float sh_input[];
    const int tiles_w = (W_out + TILE_W - 1) / TILE_W;
    const int tile_w = blockIdx.x % tiles_w;
    const int tile_h = blockIdx.x / tiles_w;
    const int h_out0 = tile_h * TILE_H;
    const int w_out0 = tile_w * TILE_W;
    const int c_out = blockIdx.y * COUT_TILE + threadIdx.z;
    const int n = blockIdx.z;
    const int h_out = h_out0 + threadIdx.y;
    const int w_out = w_out0 + threadIdx.x;
    const int in_h0 = h_out0 * stride - pad;
    const int in_w0 = w_out0 * stride - pad;
    const int in_h = (TILE_H - 1) * stride + K;
    const int in_w = (TILE_W - 1) * stride + K;
    const int plane_elems = in_h * in_w;
    const int tid = threadIdx.x + TILE_W * threadIdx.y + TILE_W * TILE_H * threadIdx.z;
    for (int i = tid; i < C_in * plane_elems; i += BLOCK_THREADS) {
        const int c = i / plane_elems;
        const int r = i - c * plane_elems;
        const int y = r / in_w;
        const int x = r - y * in_w;
        const int h_in = in_h0 + y;
        const int w_in = in_w0 + x;
        float v = 0.0f;
        if (h_in >= 0 && h_in < H_in && w_in >= 0 && w_in < W_in) {
            v = input[(((long long)n * C_in + c) * H_in + h_in) * W_in + w_in];
        }
        sh_input[i] = v;
    }
    __syncthreads();
    if (h_out >= H_out || w_out >= W_out || c_out >= C_out) return;
    const int y0 = threadIdx.y * stride;
    const int x0 = threadIdx.x * stride;
    float sum = 0.0f;
    for (int c = 0; c < C_in; ++c) {
        const float* sh_plane = sh_input + c * plane_elems;
        const float* w_ch = weight + (((long long)c_out * C_in + c) * K) * K;
        #pragma unroll 4
        for (int kh = 0; kh < K; ++kh) {
            const float* sh_row = sh_plane + (y0 + kh) * in_w;
            const float* w_row = w_ch + kh * K;
            #pragma unroll 4
            for (int kw = 0; kw < K; ++kw) {
                sum += sh_row[x0 + kw] * w_row[kw];
            }
        }
    }
    output[(((long long)n * C_out + c_out) * H_out + h_out) * W_out + w_out] = sum + bias[c_out];
}
torch::Tensor conv2d_forward(torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
                             int64_t stride, int64_t pad)
{
    TORCH_CHECK(input.is_cuda() && weight.is_cuda() && bias.is_cuda(),
                "All tensors must be on CUDA");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32 &&
                weight.scalar_type() == torch::kFloat32 &&
                bias.scalar_type() == torch::kFloat32,
                "Only float32 tensors are supported");
    TORCH_CHECK(input.dim() == 4 && weight.dim() == 4 && bias.dim() == 1,
                "Bad tensor ranks");
    auto input_c = input.contiguous();
    auto weight_c = weight.contiguous();
    auto bias_c = bias.contiguous();
    const int N     = input_c.size(0);
    const int C_in  = input_c.size(1);
    const int H_in  = input_c.size(2);
    const int W_in  = input_c.size(3);
    const int C_out = weight_c.size(0);
    const int K     = weight_c.size(2);
    TORCH_CHECK(weight_c.size(1) == C_in && weight_c.size(3) == K &&
                bias_c.size(0) == C_out, "Shape mismatch");
    const int H_out = (H_in + 2 * (int)pad - K) / (int)stride + 1;
    const int W_out = (W_in + 2 * (int)pad - K) / (int)stride + 1;
    TORCH_CHECK(H_out > 0 && W_out > 0, "Invalid output size");
    auto output = torch::empty({N, C_out, H_out, W_out}, input_c.options());
    const int tiles_h = (H_out + TILE_H - 1) / TILE_H;
    const int tiles_w = (W_out + TILE_W - 1) / TILE_W;
    const int in_h = (TILE_H - 1) * (int)stride + K;
    const int in_w = (TILE_W - 1) * (int)stride + K;
    const size_t smem_bytes = (size_t)C_in * in_h * in_w * sizeof(float);
    static int max_dynamic_smem = -1;
    if (max_dynamic_smem < 0) {
        int dev = 0;
        cudaGetDevice(&dev);
        cudaDeviceProp prop;
        cudaGetDeviceProperties(&prop, dev);
        max_dynamic_smem = (int)prop.sharedMemPerBlockOptin;
        cudaFuncSetAttribute(reinterpret_cast<const void*>(conv2d_forward_kernel),
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             max_dynamic_smem);
    }
    TORCH_CHECK(smem_bytes <= (size_t)max_dynamic_smem, "Shared memory tile too large");
    dim3 block(TILE_W, TILE_H, COUT_TILE);
    dim3 grid(tiles_w * tiles_h, (C_out + COUT_TILE - 1) / COUT_TILE, N);
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    conv2d_forward_kernel<<<grid, block, smem_bytes, stream>>>(
        input_c.data_ptr<float>(),
        weight_c.data_ptr<float>(),
        bias_c.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C_in, H_in, W_in,
        C_out, H_out, W_out,
        K, (int)stride, (int)pad);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return output;
}
'''

cpp_src = r'''
torch::Tensor conv2d_forward(torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
                             int64_t stride, int64_t pad);
'''

cuda_module = load_inline(
    name="conv2d_custom",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["conv2d_forward"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)

    def forward(self, x):
        return cuda_module.conv2d_forward(x, self.conv1.weight, self.conv1.bias, 4, 2)

